package mx.com.tiendaonline;import mx.com.tiendaonline.cliente.model.dto.command.ClienteCreateCommand;import mx.com.tiendaonline.cliente.model.entity.Cliente;import mx.com.tiendaonline.cliente.port.dao.ClienteDAO;import mx.com.tiendaonline.cliente.port.event.ClienteEventCreate;import mx.com.tiendaonline.cliente.port.repository.ClienteRepository;import mx.com.tiendaonline.cliente.service.ClienteCreateService;import mx.com.tiendaonline.producto.model.dto.command.ProductoCreateCommand;import mx.com.tiendaonline.producto.model.entity.Producto;import mx.com.tiendaonline.producto.model.entity.ProductoId;import mx.com.tiendaonline.producto.port.repository.ProductoRepository;import mx.com.tiendaonline.producto.service.ProductoCreateService;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.ArgumentMatchers.anyString;import static org.mockito.Mockito.verify;import static org.mockito.Mockito.when;@ExtendWith(MockitoExtension.class)public class ProductoCreateServiceTest {    @Mock    private ProductoRepository productoRepository;@Mockprivate ClienteDAO clienteDAO;    @Mock    private ClienteRepository clienteRepository;    @Mock    private ClienteEventCreate clienteEventCreate;    @InjectMocks    private ClienteCreateService clienteCreateService;    @InjectMocks    private ProductoCreateService productoCreateService;    @Test    void crearProductoTest(){        ProductoCreateCommand producto= new ProductoCreateCommand(null,"xbox", BigDecimal.valueOf(9000.00),10);        Producto productoGuardado = new Producto(1L,"xbox",BigDecimal.valueOf(9000.00),10);        when (productoRepository.create(any(Producto.class))).thenReturn(productoGuardado);        Producto resultado = productoCreateService.crear(producto);        assertNotNull(resultado);        assertEquals(1L,resultado.getId());        assertEquals("xbox",resultado.getNombre());    }    @Test    void crearCliente(){        ClienteCreateCommand cliente = new ClienteCreateCommand(null,"Rommel","Valdiviezo","rommelkd34@gmail.com","5590390098","milan");        Cliente clienteCreado = new Cliente(1L,"Rommel","Valdiviezo","rommelkd34@gmail.com","5590390098","milan");       when(clienteDAO.existByEmail(anyString())).thenReturn(false);        when(clienteRepository.create(any(Cliente.class))).thenReturn(clienteCreado);        Cliente resultado = clienteCreateService.crear(cliente);        assertNotNull(resultado);        assertEquals(1L,resultado.getId());        assertEquals("Rommel",resultado.getNombre());        assertEquals("Valdiviezo",resultado.getApellido());        assertEquals("rommelkd34@gmail.com",resultado.getEmail());        assertEquals("5590390098",resultado.getTelefono());        assertEquals("milan",resultado.getDireccion());        verify(clienteEventCreate).clienteCreadoEvent(any(Cliente.class));    }}